        continue;
    // A document is expected to carry anchors only where its own template
    // defines them. Some templated documents are deliberately free-form, and
    // demanding an anchored surface they never had is inventing a requirement.
    const template = renderedTemplate(level, docName);
    if (template === null || anchors(template).length === 0)
        continue;
    checked += 1;
    const body = stripFences(actual);
    const opens = [...body.matchAll(/<!--\s*ANCHOR:([a-z0-9-]+)\s*-->/gu)].map((m) => m[1]);
    const closes = [...body.matchAll(/<!--\s*\/ANCHOR:([a-z0-9-]+)\s*-->/gu)].map((m) => m[1]);
    // Retrieval chunks by anchor and generated content is merged into one, so a
    // document carrying none cannot participate in either.
    if (opens.length === 0)
        findings.push(`${docName}: no anchors found`);
    const seen = new Set();
    for (const id of opens) {
        if (seen.has(id))
            findings.push(`${docName}: duplicate anchor '${id}'`);
        seen.add(id);
    }
    for (const id of opens) {
        if (!closes.includes(id))
            findings.push(`${docName}: anchor '${id}' is never closed`);
    }
    for (const id of closes) {
        if (!opens.includes(id))
            findings.push(`${docName}: anchor '${id}' is closed but never opened`);
    }
    // A stray closer ends its region early for retrieval and merging.
    const openCounts = new Map();
    for (const id of opens)
        openCounts.set(id, (openCounts.get(id) ?? 0) + 1);
    const closeCounts = new Map();
    for (const id of closes)
        closeCounts.set(id, (closeCounts.get(id) ?? 0) + 1);
    for (const [id, closeCount] of closeCounts) {
        const openCount = openCounts.get(id) ?? 0;
        if (openCount > 0 && closeCount > openCount) {
            findings.push(`${docName}: anchor '${id}' is closed more times than it is opened`);
        }
    }
    // Quoted marker syntax is documentation, not structure: an example in
    // backticks must not read as a real nested anchor.
    nestingFindings.push(...anchorNestingFindings(docName, stripInlineCode(body)));
